local ECSComponent = import("Frame.ECS.ECSComponent")
local UIModule = CS.Engine.UI.UIModule
---@type ActivityMidFestivalBossHomeDojo
local ActivityMidFestivalBossHomeDojo = import("Game.Activity.MidFestival.BossDialog.Dojo.ActivityMidFestivalBossHomeDojo")

---@class ActivityMidFestivalBossComponent
local ActivityMidFestivalBossComponent = Class("ActivityMidFestivalBossComponent", ECSComponent)

function ActivityMidFestivalBossComponent:__init()
    self.name = "ActivityMidFestivalBossComponent"
    ---@type ActivityMidFestivalBossHomeDojo
    self._bossHomeDojo = ActivityMidFestivalBossHomeDojo.New()
end

function ActivityMidFestivalBossComponent:__delete()
end

--region public
function ActivityMidFestivalBossComponent:BossHomeReq(activityId)
    GameUtils.Request(Interfaces.OverseaMidFestivalBossHome, { activityUuid = activityId }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._bossHomeDojo:Fill(jsonData)
        local t = jsonData.hurtDrawRewardId
        self._hurtDrawRewardsHash = {}
        for k, v in pairs(t) do
            self._hurtDrawRewardsHash[checkString(v)] = true
        end
        Events.Broadcast(Constants.EventNames.MidFestivalBossHomeReq)
    end)
end

--endregion public

--region get / set
---@return ActivityMidFestivalBossHomeDojo
function ActivityMidFestivalBossComponent:GetBossHomeDojo()
    return self._bossHomeDojo
end

function ActivityMidFestivalBossComponent:IsRewardDraw(rewardId)
    return self._bossHomeDojo:IsRewardDraw(rewardId)
end

function ActivityMidFestivalBossComponent:IsCanOneKeyDrawReward()
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    -- 获取所有奖励
    local allRewards = comp:GetRankRewards()
    -- 获取所有可领取的奖励
    local historyMaxHurt = checkNumber(self._bossHomeDojo.historyMaxHurt)
    local allCanDrawButNotInListRewards = {}
    for _, reward in ipairs(allRewards) do
        ---@type MidFestivalBossDamageRewardVo
        local rewardVo = reward
        if historyMaxHurt >= checkNumber(rewardVo.upperLimit) and (not self:IsRewardDraw(rewardVo.id)) then
            table.insert(allCanDrawButNotInListRewards, rewardVo)
        end
    end
    return table.count(allCanDrawButNotInListRewards) > 0
end

--endregion get / set
return ActivityMidFestivalBossComponent